-- ============================================
-- FIX — cours Vecteurs reecrit (pedagogie, pas de copier-coller du cahier)
-- A coller dans : Supabase > SQL Editor > New query
-- ============================================
-- Reprend tout le meme contenu que le cahier (coordonnees, norme,
-- milieu, determinant/colinearite, base et repere) mais explique avec
-- des mots simples et des exemples, construit une idee a la fois, au
-- lieu de reprendre les formulations du manuel.

UPDATE cours
SET contenu = $coursJson4$[{"id": 1, "type": "texte", "content": "Un vecteur, c'est juste un trajet. Tu pars d'un point, tu arrives à un autre, et trois choses comptent : la direction (quelle route), le sens (vers où sur cette route) et la longueur (combien de distance). $\\overrightarrow{AB}$ veut dire « le trajet de A vers B ». Rien de plus compliqué que ça pour commencer — tout le reste de ce cours en découle."}, {"id": 2, "type": "definition", "content": "Imagine deux voitures qui font exactement le même trajet — même route, même direction, même distance — mais parties de deux endroits différents. On dit que ce sont les mêmes vecteurs. Peu importe où on les dessine : seuls comptent direction, sens et longueur.", "titre": "Deux vecteurs identiques"}, {"id": 3, "type": "definition", "content": "Faire une translation de vecteur u, c'est faire glisser toute une figure d'un seul coup, dans la même direction, le même sens, la même distance pour chaque point. Si A devient A', alors $\\overrightarrow{AA'}$ = $\\vec{u}$ : c'est la définition même de « glisser selon u ».", "titre": "La translation, c'est glisser"}, {"id": 4, "type": "theoreme", "content": "ABCD est un parallélogramme exactement quand $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$ — le trajet de A vers B est le même que celui de D vers C. C'est logique : si les deux côtés opposés sont « le même trajet », la figure ne peut être qu'un parallélogramme.", "titre": "Le parallélogramme, un raccourci pratique"}, {"id": 5, "type": "theoreme", "content": "Si tu vas de A à B, puis de B à C, au final tu es allé de A à C. C'est tout ce que dit Chasles : $\\overrightarrow{AB}$ + $\\overrightarrow{BC}$ = $\\overrightarrow{AC}$. Astuce pour ne pas se tromper : la lettre du milieu (B) doit être la même des deux côtés, et elle disparaît dans le résultat.", "titre": "Chasles : enchaîner deux trajets"}, {"id": 6, "type": "definition", "content": "« Direction, sens, longueur » décrits avec des mots, c'est flou. Pour être précis, on pose une grille avec deux directions de référence : i vers la droite, j vers le haut. Tout vecteur se décrit alors avec deux nombres : combien de pas selon i, combien de pas selon j. C'est exactement ce que tu faisais dans l'atelier en bougeant un point sur la grille et en lisant deux chiffres.", "titre": "Pourquoi un repère ?"}, {"id": 7, "type": "methode", "content": "$\\overrightarrow{AB}$ a pour coordonnées (x_B − x_A ; y_B − y_A) : toujours arrivée moins départ, dans cet ordre. Exemple : A(1 ; 2) et B(4 ; 6). On fait 4 − 1 = 3, puis 6 − 2 = 4. $\\overrightarrow{AB}$ a pour coordonnées (3 ; 4) : 3 pas à droite, 4 pas vers le haut.", "titre": "Les coordonnées de →AB"}, {"id": 8, "type": "methode", "content": "Une fois que chaque vecteur a deux nombres, additionner ou soustraire des vecteurs, c'est juste additionner ou soustraire ces nombres un par un : u(x ; y) et v(x′ ; y′) donnent u + v = (x + x′ ; y + y′) et u − v = (x − x′ ; y − y′). Multiplier un vecteur par un nombre k, c'est multiplier chaque coordonnée par k : k·u = (kx ; ky).", "titre": "Calculer avec les coordonnées"}, {"id": 9, "type": "definition", "content": "La norme d'un vecteur, notée ‖$\\overrightarrow{AB}$‖, c'est sa longueur réelle — pas le nombre de pas, la distance parcourue. Ça te rappelle quelque chose ? C'est Pythagore, caché : ‖$\\overrightarrow{AB}$‖ = $\\sqrt{x^2+y^2}$ où (x ; y) sont les coordonnées. Pour $\\overrightarrow{AB}$(3 ; 4) : $\\sqrt{3^2+4^2} = \\sqrt{25} = 5$.", "titre": "La norme : la vraie longueur du trajet"}, {"id": 10, "type": "definition", "content": "Le milieu d'un segment [AB], c'est la moyenne des coordonnées de A et de B — exactement comme une moyenne de notes. Milieu de [AB] = ((x_A + x_B)/2 ; (y_A + y_B)/2).", "titre": "Le milieu : pile au centre"}, {"id": 11, "type": "definition", "content": "Deux vecteurs sont colinéaires s'ils pointent dans la même direction — comme deux flèches parallèles, même si elles n'ont pas la même longueur ni le même sens. Pour le vérifier sans dessiner, il existe une formule qui vaut exactement 0 dans ce cas-là, jamais sinon : c'est le déterminant.", "titre": "Colinéarité : même direction ?"}, {"id": 12, "type": "methode", "content": "Pour u(x ; y) et v(x′ ; y′), le déterminant est det(u, v) = xy′ − x′y. On multiplie en croix, et on soustrait. Si le résultat est 0, les vecteurs sont colinéaires — et donc les droites qu'ils dirigent sont parallèles, ou les points qu'ils relient sont alignés. C'est le genre de chose qui tombe facilement au contrôle, alors autant s'entraîner dessus comme sur le reste.", "titre": "Calculer un déterminant"}, {"id": 13, "type": "exemple", "content": "A(1 ; 2) et B(4 ; 6).\n1) Coordonnées de $\\overrightarrow{AB}$ : (4 − 1 ; 6 − 2) = (3 ; 4).\n2) Norme : $\\sqrt{3^2+4^2} = \\sqrt{25} = 5$.\n3) Milieu de [AB] : ((1+4)/2 ; (2+6)/2) = (2,5 ; 4).", "titre": "Exemple résolu — coordonnées, norme, milieu"}, {"id": 14, "type": "exemple", "content": "A(−2 ; −1), B(2 ; −3), C(−4 ; 4), D(6 ; −1).\n1) $\\overrightarrow{AB}$ = (2−(−2) ; −3−(−1)) = (4 ; −2).\n2) $\\overrightarrow{CD}$ = (6−(−4) ; −1−4) = (10 ; −5).\n3) det($\\overrightarrow{AB}$, $\\overrightarrow{CD}$) = 4 × (−5) − 10 × (−2) = −20 + 20 = 0.\n4) Le déterminant est nul, donc $\\overrightarrow{AB}$ et $\\overrightarrow{CD}$ sont colinéaires : les droites (AB) et (CD) sont parallèles.", "titre": "Exemple résolu — colinéarité"}, {"id": 15, "type": "remarque", "content": "Lire les lettres dans le mauvais ordre : pour ABCD, c'est $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$, pas $\\overrightarrow{AB}$ = $\\overrightarrow{CD}$.\nFaire départ moins arrivée au lieu d'arrivée moins départ : le signe change.\nOublier les parenthèses avec un négatif : 5 − (−2) = 7, pas 3.\nConfondre colinéaire et égal : colinéaire veut juste dire « même direction », pas « même trajet ».", "titre": "Pièges classiques"}, {"id": 16, "type": "remarque", "content": "La flèche se note toujours au-dessus des lettres : $\\overrightarrow{AB}$, jamais AB tout court — sanctionné si elle manque. Et le programme de ce chapitre, c'est tout en bloc : coordonnées, norme, milieu, ET colinéarité/déterminant. Pas juste l'égalité de deux vecteurs.", "titre": "Pour le contrôle"}]$coursJson4$
WHERE niveau = '2nde' AND chapitre = 'Vecteurs dans le plan';
